head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF30618.xml"; //공시담당자등 교육참가현황(유)


//자료수정 시 팝업창으로 넘길 데이터
scwin.key_edu_partc_id = ""; //PK
scwin.key_isur_cd = ""; //회사코드
scwin.key_com_abbrv = ""; //회사명
scwin.key_chrg_tp_cd = ""; //담당자구분코드
scwin.key_edu_id = ""; //교육일정코드
scwin.key_chrg_nm = ""; // 선택된참가자명
scwin.key_edu_nm = ""; // 선택과정명
scwin.key_edu_ack_tm = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 이수시간


scwin.fn_Init = function() {
    /*
    	var ToDay = new Date();
    	var yyyy = parseInt(ToDay.getYear(), 10);
    	yyyy = yyyy +1; // 박태일 부부장님 요청으로 차년도까지 조회 가능하도록 수정. 2013.08.22 by ldj
    	var str = "^전체";

    	for (var i = yyyy; i >= 2010 ; i--)
    	{
    		str += "," + i + "^" + i;
    	}

    	cmb_YYYY.CBData = str;
    */
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
    dts_edu.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=SECU_EDU_TP_CD";
    dts_edu.Reset();
};
scwin.fn_setYear = function() {
    dts_year.DataID = encodeURI("/ListedCompany.do?method=selectMinMaxYear&outputMessageId=DISCLS_MIN_MAX_YEAR_OUT");
    dts_year.Reset();
    var minYear = dts_year.getCellData(1, "MIN_YEAR");
    var maxYear = dts_year.getCellData(1, "MAX_YEAR");
    var str = "^전체";
    for (var i = maxYear; i >= minYear; i--) {
        str += "," + i + "^" + i;
    }
    //alert(str);
    cmb_YYYY.CBData = str;

    //default 현재년도 
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    $c.stf.setObjectValue(cmb_YYYY, yyyy);
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=listDisclsEduPartc";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&EDU_KIND_CD=" + $c.stf.getObjectValue(cmb_EDU_KIND_CD);
    url += "&YYYY=" + $c.stf.getObjectValue(cmb_YYYY);
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
    url += "&SECU_EDU_TP_CD=" + $c.stf.getObjectValue(cmb_edu); //교육구분
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.getDisclsEduName = function(gubun) {
    dts_EduCrsNm.DataID = "/ListedCompany.do?method=getDisclsEduName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&CHRG_TP_CD=" + gubun;
    dts_EduCrsNm.Reset();
};


//자료수정 시 팝업창으로 넘길 데이터 셋팅
scwin.fn_SetVariable = function(row) {
    scwin.key_edu_partc_id = dts_MASTER.getCellData(row, "EDU_PARTC_ID"); //PK
    scwin.key_isur_cd = dts_MASTER.getCellData(row, "ISUR_CD"); //회사코드
    scwin.key_com_abbrv = dts_MASTER.getCellData(row, "COM_ABBRV"); //회사명	
    scwin.key_chrg_tp_cd = dts_MASTER.getCellData(row, "CHRG_TP_CD"); //담당자구분코드
    scwin.key_edu_id = dts_MASTER.getCellData(row, "EDU_SCHDL_ID"); //교육일정코드
    scwin.key_chrg_nm = dts_MASTER.getCellData(row, "CHRG_NM"); // 선택된참가자명
    scwin.key_edu_nm = dts_MASTER.getCellData(row, "DISCLS_EDU_CRS_NM"); // 선택과정명
    scwin.key_edu_ack_tm = dts_MASTER.getCellData(row, "EDU_ACK_TM"); // 이수시간

};


//자료입력 시 팝업창으로 넘길 데이터 초기화
scwin.fn_ResetVariable = function() {
    scwin.key_edu_partc_id = ""; //PK
    scwin.key_isur_cd = ""; //회사코드
    scwin.key_chrg_tp_cd = ""; //담당자구분코드
    scwin.key_edu_id = ""; //교육일정코드
    scwin.key_chrg_nm = ""; // 선택된참가자명
    scwin.key_edu_nm = ""; // 선택과정명
    scwin.key_edu_ack_tm = ""; // 이수시간

};


//입력 또는 수정 팝업창 띄우기
scwin.fn_readDisclsEdu = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30625", "/issueinfo/ULDSTF30625.gfm", "교육참가현황 등록", 50, 20, 860, 635, "window");
};


//공시담당자 교육참가이력 변경 버튼 클릭 시 팝업창 띄우기
scwin.fn_DisclsEduHistory = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30627", "/issueinfo/ULDSTF30627.gfm", "공시담당자 교육참가이력 변경", 50, 20, 860, 635, "window");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_MASTER.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == 'DISCLS_EDU_CRS_NM') {
        scwin.fn_SetVariable(row);
        scwin.fn_readDisclsEdu();
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "공시교육참가현황", "", "8");
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_setYear();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    $c.stf.setObjectValue(txb_isur_cd, $c.stf.getQuery(frame.srcUrl, "ISUR_CD"));
    $c.stf.setObjectValue(txb_com_abbrv, $c.stf.getQuery(frame.srcUrl, "COM_NM"));
    scwin.fn_Search();
};
scwin.btn_Input_onclick = function() {
    scwin.fn_ResetVariable();
    scwin.fn_readDisclsEdu();
};
scwin.btn_Snd_onclick = function() {
    scwin.fn_DisclsEduHistory();
};
